targets.root_selector:
(
  /* タイムスタンプ */
  $ts := $.attributes[attrName = "systemTimestamp"].values;

  /* adaptability (ad) */
  $adAction := $.attributes[attrName = "analysis"].values.adaptability.action;
  $adDataCo2 := $.attributes[attrName = "analysis"].values.adaptability.data.co2;
  $adDataHumidity := $.attributes[attrName = "analysis"].values.adaptability.data.humidity;
  $adDataIlluminance := $.attributes[attrName = "analysis"].values.adaptability.data.illuminance;
  $adDataPitch := $.attributes[attrName = "analysis"].values.adaptability.data.pitch;
  $adDataRoll := $.attributes[attrName = "analysis"].values.adaptability.data.roll;
  $adDataTemperature := $.attributes[attrName = "analysis"].values.adaptability.data.temperature;
  $adDataYaw := $.attributes[attrName = "analysis"].values.adaptability.data.yaw;
  $adDiagnosis := $.attributes[attrName = "analysis"].values.adaptability.diagnosis;
  $adStatus := $.attributes[attrName = "analysis"].values.adaptability.status;

  /* costEfficiency (ce) */
  $ceAction := $.attributes[attrName = "analysis"].values.costEfficiency.action;
  $ceDataHarvestCount := $.attributes[attrName = "analysis"].values.costEfficiency.data.harvestCount;
  $ceDataOperatingTime := $.attributes[attrName = "analysis"].values.costEfficiency.data.operatingTime;
  $ceDataTotalStopTime := $.attributes[attrName = "analysis"].values.costEfficiency.data.totalStopTime;
  $ceDiagnosis := $.attributes[attrName = "analysis"].values.costEfficiency.diagnosis;
  $ceStatus := $.attributes[attrName = "analysis"].values.costEfficiency.status;

  /* dataUtilization (du) */
  $duAction := $.attributes[attrName = "analysis"].values.dataUtilization.action;
  $duDiagnosis := $.attributes[attrName = "analysis"].values.dataUtilization.diagnosis;
  $duStatus := $.attributes[attrName = "analysis"].values.dataUtilization.status;

  /* durability (db) */
  $dbAction := $.attributes[attrName = "analysis"].values.durability.action;
  $dbDataFailureCount := $.attributes[attrName = "analysis"].values.durability.data.failureCount;
  $dbDataOperatingTime := $.attributes[attrName = "analysis"].values.durability.data.operatingTime;
  $dbDataProcessingTime := $.attributes[attrName = "analysis"].values.durability.data.processingTime;
  $dbDataRobotSpeed := $.attributes[attrName = "analysis"].values.durability.data.robotSpeed;
  $dbDataStatusCode := $.attributes[attrName = "analysis"].values.durability.data.statusCode;
  $dbDataTotalStopTime := $.attributes[attrName = "analysis"].values.durability.data.totalStopTime;
  $dbDiagnosis := $.attributes[attrName = "analysis"].values.durability.diagnosis;
  $dbMetricsMtbf := $.attributes[attrName = "analysis"].values.durability.metrics.mtbf;
  $dbMetricsOperationRate := $.attributes[attrName = "analysis"].values.durability.metrics.operationRate;
  $dbStatus := $.attributes[attrName = "analysis"].values.durability.status;

  /* ethics (et) */
  $etAction := $.attributes[attrName = "analysis"].values.ethics.action;
  $etDiagnosis := $.attributes[attrName = "analysis"].values.ethics.diagnosis;
  $etStatus := $.attributes[attrName = "analysis"].values.ethics.status;

  /* harvestAccuracy (ha) */
  $haAction := $.attributes[attrName = "analysis"].values.harvestAccuracy.action;
  $haDataDetectionCount := $.attributes[attrName = "analysis"].values.harvestAccuracy.data.detectionCount;
  $haDataHarvestCount := $.attributes[attrName = "analysis"].values.harvestAccuracy.data.harvestCount;
  $haDiagnosis := $.attributes[attrName = "analysis"].values.harvestAccuracy.diagnosis;
  $haMetricsAmbiguityRate := $.attributes[attrName = "analysis"].values.harvestAccuracy.metrics.ambiguityRate;
  $haMetricsUncertainCount := $.attributes[attrName = "analysis"].values.harvestAccuracy.metrics.uncertainCount;
  $haStatus := $.attributes[attrName = "analysis"].values.harvestAccuracy.status;

  /* harvestSpeed (hs) */
  $hsAction := $.attributes[attrName = "analysis"].values.harvestSpeed.action;
  $hsDataOperatingTime := $.attributes[attrName = "analysis"].values.harvestSpeed.data.operatingTime;
  $hsDataProcessingTime := $.attributes[attrName = "analysis"].values.harvestSpeed.data.processingTime;
  $hsDataRobotSpeed := $.attributes[attrName = "analysis"].values.harvestSpeed.data.robotSpeed;
  $hsDataStatusCode := $.attributes[attrName = "analysis"].values.harvestSpeed.data.statusCode;
  $hsDataTravelStopTime := $.attributes[attrName = "analysis"].values.harvestSpeed.data.travelStopTime;
  $hsDiagnosis := $.attributes[attrName = "analysis"].values.harvestSpeed.diagnosis;
  $hsMetricsStopRate := $.attributes[attrName = "analysis"].values.harvestSpeed.metrics.stopRate;
  $hsStatus := $.attributes[attrName = "analysis"].values.harvestSpeed.status;

  /* maintainability (mn) */
  $mnAction := $.attributes[attrName = "analysis"].values.maintainability.action;
  $mnDataFailureCount := $.attributes[attrName = "analysis"].values.maintainability.data.failureCount;
  $mnDataPartFailureProbsArm := $.attributes[attrName = "analysis"].values.maintainability.data.partFailureProbs.arm;
  $mnDataPartFailureProbsCamera := $.attributes[attrName = "analysis"].values.maintainability.data.partFailureProbs.camera;
  $mnDataPartFailureProbsCommunication := $.attributes[attrName = "analysis"].values.maintainability.data.partFailureProbs.communication;
  $mnDataPartFailureProbsControlUnit := $.attributes[attrName = "analysis"].values.maintainability.data.partFailureProbs.controlUnit;
  $mnDataPartFailureProbsHand := $.attributes[attrName = "analysis"].values.maintainability.data.partFailureProbs.hand;
  $mnDataPartFailureProbsPower := $.attributes[attrName = "analysis"].values.maintainability.data.partFailureProbs.power;
  $mnDataPartFailureProbsTray := $.attributes[attrName = "analysis"].values.maintainability.data.partFailureProbs.tray;
  $mnDataPartFailureProbsWheels := $.attributes[attrName = "analysis"].values.maintainability.data.partFailureProbs.wheels;
  $mnDataTotalStopTime := $.attributes[attrName = "analysis"].values.maintainability.data.totalStopTime;
  $mnDiagnosis := $.attributes[attrName = "analysis"].values.maintainability.diagnosis;
  $mnMetricsMttr := $.attributes[attrName = "analysis"].values.maintainability.metrics.mttr;
  $mnStatus := $.attributes[attrName = "analysis"].values.maintainability.status;

  /* operability (op) */
  $opAction := $.attributes[attrName = "analysis"].values.operability.action;
  $opDataOperationErrors := $.attributes[attrName = "analysis"].values.operability.data.operationErrors;
  $opDataOperationSteps := $.attributes[attrName = "analysis"].values.operability.data.operationSteps;
  $opDataOperationTime := $.attributes[attrName = "analysis"].values.operability.data.operationTime;
  $opDiagnosis := $.attributes[attrName = "analysis"].values.operability.diagnosis;
  $opMetricsOperationErrorRate := $.attributes[attrName = "analysis"].values.operability.metrics.operationErrorRate;
  $opStatus := $.attributes[attrName = "analysis"].values.operability.status;

  /* safety (sa) */
  $saAction := $.attributes[attrName = "analysis"].values.safety.action;
  $saDataRiskDetectionCount := $.attributes[attrName = "analysis"].values.safety.data.riskDetectionCount;
  $saDataSafetyActivationCount := $.attributes[attrName = "analysis"].values.safety.data.safetyActivationCount;
  $saDiagnosis := $.attributes[attrName = "analysis"].values.safety.diagnosis;
  $saStatus := $.attributes[attrName = "analysis"].values.safety.status;

  /* 出力 */
  $map($ts, function($v, $i) {
    {
      "timestamp": $v,

      /* ad */
      "adAction": $adAction[$i],
      "adDataCo2": $adDataCo2[$i],
      "adDataHumidity": $adDataHumidity[$i],
      "adDataIlluminance": $adDataIlluminance[$i],
      "adDataPitch": $adDataPitch[$i],
      "adDataRoll": $adDataRoll[$i],
      "adDataTemperature": $adDataTemperature[$i],
      "adDataYaw": $adDataYaw[$i],
      "adDiagnosis": $adDiagnosis[$i],
      "adStatus": $adStatus[$i],

      /* ce */
      "ceAction": $ceAction[$i],
      "ceDataHarvestCount": $ceDataHarvestCount[$i],
      "ceDataOperatingTime": $ceDataOperatingTime[$i],
      "ceDataTotalStopTime": $ceDataTotalStopTime[$i],
      "ceDiagnosis": $ceDiagnosis[$i],
      "ceStatus": $ceStatus[$i],

      /* du */
      "duAction": $duAction[$i],
      "duDiagnosis": $duDiagnosis[$i],
      "duStatus": $duStatus[$i],

      /* db */
      "dbAction": $dbAction[$i],
      "dbDataFailureCount": $dbDataFailureCount[$i],
      "dbDataOperatingTime": $dbDataOperatingTime[$i],
      "dbDataProcessingTime": $dbDataProcessingTime[$i],
      "dbDataRobotSpeed": $dbDataRobotSpeed[$i],
      "dbDataStatusCode": $dbDataStatusCode[$i],
      "dbDataTotalStopTime": $dbDataTotalStopTime[$i],
      "dbDiagnosis": $dbDiagnosis[$i],
      "dbMetricsMtbf": $dbMetricsMtbf[$i],
      "dbMetricsOperationRate": $dbMetricsOperationRate[$i],
      "dbStatus": $dbStatus[$i],

      /* et */
      "etAction": $etAction[$i],
      "etDiagnosis": $etDiagnosis[$i],
      "etStatus": $etStatus[$i],

      /* ha */
      "haAction": $haAction[$i],
      "haDataDetectionCount": $haDataDetectionCount[$i],
      "haDataHarvestCount": $haDataHarvestCount[$i],
      "haDiagnosis": $haDiagnosis[$i],
      "haMetricsAmbiguityRate": $haMetricsAmbiguityRate[$i],
      "haMetricsUncertainCount": $haMetricsUncertainCount[$i],
      "haStatus": $haStatus[$i],

      /* hs */
      "hsAction": $hsAction[$i],
      "hsDataOperatingTime": $hsDataOperatingTime[$i],
      "hsDataProcessingTime": $hsDataProcessingTime[$i],
      "hsDataRobotSpeed": $hsDataRobotSpeed[$i],
      "hsDataStatusCode": $hsDataStatusCode[$i],
      "hsDataTravelStopTime": $hsDataTravelStopTime[$i],
      "hsDiagnosis": $hsDiagnosis[$i],
      "hsMetricsStopRate": $hsMetricsStopRate[$i],
      "hsStatus": $hsStatus[$i],

      /* mn */
      "mnAction": $mnAction[$i],
      "mnDataFailureCount": $mnDataFailureCount[$i],
      "mnDataPartFailureProbsArm": $mnDataPartFailureProbsArm[$i],
      "mnDataPartFailureProbsCamera": $mnDataPartFailureProbsCamera[$i],
      "mnDataPartFailureProbsCommunication": $mnDataPartFailureProbsCommunication[$i],
      "mnDataPartFailureProbsControlUnit": $mnDataPartFailureProbsControlUnit[$i],
      "mnDataPartFailureProbsHand": $mnDataPartFailureProbsHand[$i],
      "mnDataPartFailureProbsPower": $mnDataPartFailureProbsPower[$i],
      "mnDataPartFailureProbsTray": $mnDataPartFailureProbsTray[$i],
      "mnDataPartFailureProbsWheels": $mnDataPartFailureProbsWheels[$i],
      "mnDataTotalStopTime": $mnDataTotalStopTime[$i],
      "mnDiagnosis": $mnDiagnosis[$i],
      "mnMetricsMttr": $mnMetricsMttr[$i],
      "mnStatus": $mnStatus[$i],

      /* op */
      "opAction": $opAction[$i],
      "opDataOperationErrors": $opDataOperationErrors[$i],
      "opDataOperationSteps": $opDataOperationSteps[$i],
      "opDataOperationTime": $opDataOperationTime[$i],
      "opDiagnosis": $opDiagnosis[$i],
      "opMetricsOperationErrorRate": $opMetricsOperationErrorRate[$i],
      "opStatus": $opStatus[$i],

      /* sa */
      "saAction": $saAction[$i],
      "saDataRiskDetectionCount": $saDataRiskDetectionCount[$i],
      "saDataSafetyActivationCount": $saDataSafetyActivationCount[$i],
      "saDiagnosis": $saDiagnosis[$i],
      "saStatus": $saStatus[$i]
    }
  })
)
